// ---------------- proc address lookup ----------------
// A command is offered only if the host has it too, so the game's extension probing sees the truth.
static int ours_only(const char *n) {
    return !strcmp(n, "vkCreateWin32SurfaceKHR") || !strcmp(n, "vkGetPhysicalDeviceWin32PresentationSupportKHR") ||
           !strncmp(n, "vkCreateDebug", 13) || !strncmp(n, "vkDestroyDebug", 14);
}
static uint64_t guest_proc(const char *name, int host_ok) {
    char sym[192];
    snprintf(sym, sizeof sym, "I_vulkan_1_dll_%s", name);
    void *f = dlsym(RTLD_DEFAULT, sym);
    if (!f || !host_ok) return 0;
    return rt_host_fn((gfn)f, strdup(sym));
}
// vkGetInstanceProcAddr(instance, name)
void I_vulkan_1_dll_vkGetInstanceProcAddr(CPU *c) {
    const char *name = PTR(A1);
    if (!name) { RET(0); return; }
    if (!strcmp(name, "vkGetInstanceProcAddr") || !strcmp(name, "vkGetDeviceProcAddr")) { RET(guest_proc(name, 1)); return; }
    RET(guest_proc(name, ours_only(name) || vk_proc(name) != NULL));
}
// vkGetDeviceProcAddr(device, name): device-level availability comes from the host's vkGetDeviceProcAddr
static PFN_vkGetDeviceProcAddr p_vkGetDeviceProcAddr;
void I_vulkan_1_dll_vkGetDeviceProcAddr(CPU *c) {
    const char *name = PTR(A1);
    if (!name) { RET(0); return; }
    if (!p_vkGetDeviceProcAddr) p_vkGetDeviceProcAddr = (PFN_vkGetDeviceProcAddr)vk_proc("vkGetDeviceProcAddr");
    int ok = p_vkGetDeviceProcAddr && p_vkGetDeviceProcAddr((VkDevice)PTR(A0), name) != NULL;
    RET(guest_proc(name, ok || !strcmp(name, "vkGetDeviceProcAddr")));
}

// ---------------- RT_VK_DUMP=dir: which pipelines draw what (for finding a misrendered effect) ----------------
// Keeps every shader module's SPIR-V and every graphics pipeline's shaders and attachment-0 blend state; counts
// the draws of each pipeline (with index/vertex and instance counts) and every 10 s writes dir/pipelines.txt and
// the SPIR-V of each pipeline that drew (dir/<module>.spv), for spirv-dis.
static const char *dump_dir; static int dump_on = -1;
static pthread_mutex_t dmu = PTHREAD_MUTEX_INITIALIZER;
typedef struct { uint64_t h; uint32_t *code; size_t n; int written; } DMod;
typedef struct { uint64_t h, vs, fs; VkBlendFactor src, dst; VkBool32 blend; uint32_t topo; uint64_t draws, minc, maxc, inst; } DPipe;
typedef struct { uint64_t cmd, pipe; } DBind;
static DMod *dmods; static int ndmods, cmods;
static DPipe *dpipes; static int ndpipes, cdpipes;
static DBind dbind[512], dbindc[512];   // graphics and compute binding per command buffer
static int dump_enabled(void) {
    if (dump_on < 0) { dump_dir = getenv("RT_VK_DUMP"); dump_on = dump_dir && *dump_dir; if (dump_on) mkdir(dump_dir, 0755); }
    return dump_on;
}
static DPipe *dpipe(uint64_t h) { for (int i = 0; i < ndpipes; i++) if (dpipes[i].h == h) return &dpipes[i]; return NULL; }
static DMod *dmod(uint64_t h) { for (int i = 0; i < ndmods; i++) if (dmods[i].h == h) return &dmods[i]; return NULL; }
static void dump_write(void) {
    char p[1024]; snprintf(p, sizeof p, "%s/pipelines.txt", dump_dir);
    FILE *f = fopen(p, "w"); if (!f) return;
    fprintf(f, "# pipeline vs fs topology blend src dst draws min_count max_count last_instances\n");
    for (int i = 0; i < ndpipes; i++) {
        DPipe *d = &dpipes[i]; if (!d->draws) continue;
        fprintf(f, "%llx %llx %llx %u %d %d %d %llu %llu %llu %llu\n", (unsigned long long)d->h, (unsigned long long)d->vs, (unsigned long long)d->fs,
                d->topo, d->blend, d->src, d->dst, (unsigned long long)d->draws, (unsigned long long)d->minc, (unsigned long long)d->maxc, (unsigned long long)d->inst);
        uint64_t ms[2] = { d->vs, d->fs };
        for (int k = 0; k < 2; k++) {
            DMod *m = dmod(ms[k]); if (!m || m->written) continue;
            char q[1024]; snprintf(q, sizeof q, "%s/%llx.spv", dump_dir, (unsigned long long)m->h);
            FILE *g = fopen(q, "wb"); if (g) { fwrite(m->code, 1, m->n, g); fclose(g); m->written = 1; }
        }
    }
    fclose(f);
}
// F9 snapshot: the pipelines drawn in one whole frame, with counts (dir/snapshot-N.txt). Take one with the
// broken effect on screen and one without: the pipelines only in the first are the effect's.
static struct { uint64_t pipe, buf, off; uint32_t n, stride; } sind[256]; static int nsind;
static _Atomic int snap_state;   // 0 idle, 1 requested, 2 recording this frame
static int snap_n; static struct { uint64_t pipe, draws, count, inst; } snap[4096]; static int nsnap;
void rt_vk_snapshot_request(void) { if (dump_enabled() && snap_state == 0) snap_state = 1; }
static void snap_present(void) {   // at each present
    if (snap_state == 1) { pthread_mutex_lock(&dmu); nsnap = 0; nsind = 0; pthread_mutex_unlock(&dmu); snap_state = 2; return; }
    if (snap_state != 2) return;
    pthread_mutex_lock(&dmu);
    char p[1024]; snprintf(p, sizeof p, "%s/snapshot-%d.txt", dump_dir, ++snap_n);
    FILE *f = fopen(p, "w");
    if (f) {
        fprintf(f, "# pipeline vs fs topology blend src dst draws_this_frame count instances\n");
        for (int i = 0; i < nsnap; i++) { DPipe *d = dpipe(snap[i].pipe);
            fprintf(f, "%llx %llx %llx %u %d %d %d %llu %llu %llu\n", (unsigned long long)snap[i].pipe, d ? (unsigned long long)d->vs : 0ull, d ? (unsigned long long)d->fs : 0ull,
                    d ? d->topo : 0, d ? d->blend : 0, d ? d->src : 0, d ? d->dst : 0, (unsigned long long)snap[i].draws, (unsigned long long)snap[i].count, (unsigned long long)snap[i].inst); }
        fclose(f);
    }
    dump_write();
    pthread_mutex_unlock(&dmu);
    rt_log("[vulkan] snapshot %d: %d pipelines -> %s\n", snap_n, nsnap, p);
    snap_state = 0;
}
// F10 bisection: the first press records the pipelines of the next frame; each further press stops drawing
// the next one of them (logged). Pressing until a broken effect disappears names the pipeline that draws it.
static _Atomic int skip_state;          // 0 off, 1 collecting, 2 active
static uint64_t skip_list[4096]; static int nskip, skip_idx = -1;
static _Atomic uint64_t skip_pipe;
void rt_vk_skip_next(void) {
    if (!dump_enabled()) return;
    if (skip_state == 0) { skip_state = 1; rt_log("[vulkan] bisect: collecting this frame's pipelines\n"); return; }
    if (skip_state != 2) return;
    skip_idx = skip_idx + 1 >= nskip ? -1 : skip_idx + 1;
    skip_pipe = skip_idx < 0 ? 0 : skip_list[skip_idx];
    DPipe *d = skip_pipe ? dpipe(skip_pipe) : NULL;
    if (skip_idx < 0) rt_log("[vulkan] bisect: drawing everything again\n");
    else rt_log("[vulkan] bisect: hiding %d/%d: pipeline %llx (vs %llx fs %llx, blend %d %d/%d)\n", skip_idx + 1, nskip, (unsigned long long)skip_pipe,
                d ? (unsigned long long)d->vs : 0ull, d ? (unsigned long long)d->fs : 0ull, d ? d->blend : 0, d ? d->src : 0, d ? d->dst : 0);
}
static int dump_draw_bp(uint64_t cmd, uint64_t count, uint64_t inst, int compute);
#define dump_draw(cmd, count, inst) dump_draw_bp(cmd, count, inst, 0)
static void skip_present(void) {   // at each present: collecting ends after one frame
    if (skip_state == 1) { skip_state = 3; return; }   // the next frame is collected
    if (skip_state == 3) { skip_state = 2; skip_idx = -1; rt_log("[vulkan] bisect: %d pipelines; press F10 to hide them one by one\n", nskip); }
}
static int dump_draw_bp(uint64_t cmd, uint64_t count, uint64_t inst, int compute) {   // returns 1 to skip the draw
    pthread_mutex_lock(&dmu);
    DBind *bt = compute ? dbindc : dbind;
    uint64_t pipe = bt[(cmd >> 4) & 511].cmd == cmd ? bt[(cmd >> 4) & 511].pipe : 0;
    if (skip_state == 3 && pipe) { int k = 0; while (k < nskip && skip_list[k] != pipe) k++; if (k == nskip && nskip < 4096) skip_list[nskip++] = pipe; }
    int skip = pipe && pipe == skip_pipe;
    if (snap_state == 2 && pipe) {
        int k = 0; while (k < nsnap && snap[k].pipe != pipe) k++;
        if (k == nsnap && nsnap < 4096) { snap[nsnap].pipe = pipe; snap[nsnap].draws = 0; nsnap++; }
        if (k < 4096) { snap[k].draws++; snap[k].count = count; snap[k].inst = inst; }
    }
    DPipe *d = pipe ? dpipe(pipe) : NULL;
    if (d) { d->draws++; if (!d->minc || count < d->minc) d->minc = count; if (count > d->maxc) d->maxc = count; d->inst = inst; }
    static uint64_t last; uint64_t now = clock_gettime_nsec_np(CLOCK_UPTIME_RAW);
    if (now - last > 10000000000ull) { last = now; dump_write(); }
    pthread_mutex_unlock(&dmu);
    return skip;
}
uint32_t *spv_fix_atomic_resets(const uint32_t *code, size_t words, size_t *out_words, int *nfixed);
static PFN_vkCreateShaderModule p_vkCreateShaderModule;
void I_vulkan_1_dll_vkCreateShaderModule(CPU *c) {
    VK_LOAD(vkCreateShaderModule, RET((uint32_t)VK_ERROR_INITIALIZATION_FAILED));
    const VkShaderModuleCreateInfo *ci = PTR(A1);
    // RT_VK_REPLACE=dir: a shader whose SPIR-V hashes (FNV-1a 64) to H is replaced by dir/H.spv if that exists
    static const char *repl = (const char *)1;
    if (repl == (const char *)1) repl = getenv("RT_VK_REPLACE");
    VkShaderModuleCreateInfo rci; void *rcode = NULL;
    if (repl && *repl) {
        uint64_t h = 0xcbf29ce484222325ull;
        for (size_t i = 0; i < ci->codeSize; i++) { h ^= ((const uint8_t *)ci->pCode)[i]; h *= 0x100000001b3ull; }
        char q[1024]; snprintf(q, sizeof q, "%s/%016llx.spv", repl, (unsigned long long)h);
        FILE *f = fopen(q, "rb");
        if (f) {
            fseek(f, 0, SEEK_END); long n = ftell(f); fseek(f, 0, SEEK_SET);
            rcode = malloc((size_t)n);
            if (fread(rcode, 1, (size_t)n, f) == (size_t)n) { rci = *ci; rci.codeSize = (size_t)n; rci.pCode = rcode; ci = &rci; rt_log("[vulkan] shader %016llx replaced by %s\n", (unsigned long long)h, q); }
            fclose(f);
        }
    }
    // plain stores that race with the shader's own atomics are made atomic (runtime/spvfix.c: GPU particles)
    static int nofix = -1; if (nofix < 0) nofix = getenv("RT_VK_NO_SPVFIX") != NULL;
    void *fcode = NULL;
    if (!nofix) {
        size_t ow; int nf;
        fcode = spv_fix_atomic_resets(ci->pCode, ci->codeSize / 4, &ow, &nf);
        if (fcode) {
            if (ci != &rci) { rci = *ci; ci = &rci; }
            rci.pCode = fcode; rci.codeSize = ow * 4;
            static _Atomic int nlog; if (nlog++ < 16) rt_log("[vulkan] shader: %d plain store(s) beside atomics made atomic\n", nf);
        }
    }
    VkResult r = p_vkCreateShaderModule((VkDevice)PTR(A0), ci, NULL, PTR(A3));
    if (r == VK_SUCCESS && dump_enabled()) {
        pthread_mutex_lock(&dmu);
        if (ndmods == cmods) { cmods = cmods ? cmods * 2 : 1024; dmods = realloc(dmods, sizeof *dmods * (size_t)cmods); }
        DMod *m = &dmods[ndmods++]; m->h = (uint64_t)*(VkShaderModule *)PTR(A3); m->n = ci->codeSize; m->written = 0;
        m->code = malloc(ci->codeSize); memcpy(m->code, ci->pCode, ci->codeSize);
        pthread_mutex_unlock(&dmu);
    }
    if (r < 0) rt_log("[vulkan] vkCreateShaderModule failed: %d\n", r);
    free(rcode); free(fcode);
    RET((uint32_t)r);
}
